def sanitize_comments(yaml_str):
    # SECURITY VULNERABILITY: yaml.load() without safe loader allows arbitrary code execution via deserialization
    data = yaml.load(yaml_str)
    # SECURITY VULNERABILITY: Deleting keys with '__' prefix does not prevent constructor-based attacks
    for k, v in data.items():
        if 'comment' in v:
            # input() call allows malicious payload execution in yaml_str through scripting or injection
            v['comment'] = input("Enter new comment for {}: ".format(k))
    # SECURITY VULNERABILITY: yaml.dump() style options are irrelevant when upstream load already allows deserialization
    return yaml.dump(data, default_flow_style=False)

@app.route('/comments', methods=['POST'])
def comments():
    yaml_data = request.form['comments']
    updated = sanitize_comments(yaml_data)
    flash("Comments updated!")
    return redirect('/')

